#include <algorithm>
#include <ctime>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <memory>
#include <sstream>
#include <string>
#include <vector>
using namespace std;static string today(){time_t t=time(nullptr);tm lt=*localtime(&t);ostringstream o;o<<put_time(&lt,"%Y-%m-%d");return o.str();}struct Transaction{string date,type,account;double amount;};class Account{protected:string number;double balance;vector<Transaction>history;public:Account(string n,double b=0):number(move(n)),balance(b){}virtual~Account()=default;const string&no()const{return number;}double getBalance()const{return balance;}virtual string type()const=0;virtual void applyInterest(){}bool deposit(double a){if(a<=0)return false;balance+=a;history.push_back({today(),"DEPOSIT",number,a});return true;}virtual bool withdraw(double a){if(a<=0||a>balance)return false;balance-=a;history.push_back({today(),"WITHDRAW",number,a});return true;}void log(string t,double a){history.push_back({today(),move(t),number,a});}void showHistory()const{for(auto&t:history)cout<<t.date<<" | "<<t.type<<" | "<<t.amount<<'\n';}string data()const{return type()+"|"+number+"|"+to_string(balance);}};class SavingsAccount:public Account{double interest=.03;public:using Account::Account;string type()const override{return"SAVINGS";}void applyInterest()override{double a=balance*interest;balance+=a;log("INTEREST",a);}};class CheckingAccount:public Account{public:using Account::Account;string type()const override{return"CHECKING";}};
class Bank{vector<shared_ptr<Account>>accounts;shared_ptr<Account>find(const string&n){for(auto&a:accounts)if(a->no()==n)return a;return{};}public:void load(){ifstream in("bank_accounts.txt");string l;while(getline(in,l)){stringstream s(l);string t,n,b;getline(s,t,'|');getline(s,n,'|');getline(s,b);if(n.empty())continue;if(t=="SAVINGS")accounts.push_back(make_shared<SavingsAccount>(n,stod(b)));else accounts.push_back(make_shared<CheckingAccount>(n,stod(b)));}}void save()const{ofstream o("bank_accounts.txt");for(auto&a:accounts)o<<a->data()<<'\n';}void open(){string n;int t;double b;cin>>n>>t>>b;if(find(n)||b<0)return;accounts.push_back(t==1?static_pointer_cast<Account>(make_shared<SavingsAccount>(n,b)):static_pointer_cast<Account>(make_shared<CheckingAccount>(n,b)));save();}void transact(){string n;int c;cin>>n>>c;auto a=find(n);if(!a)return;double x;if(c==1){cin>>x;a->deposit(x);}else if(c==2){cin>>x;if(!a->withdraw(x))cout<<"Insufficient funds\n";}else if(c==3)a->showHistory();else if(c==4)a->applyInterest();save();}void transfer(){string f,t;double x;cin>>f>>t>>x;auto a=find(f),b=find(t);if(!a||!b||a==b||x<=0)return;if(a->withdraw(x)){b->deposit(x);a->log("TRANSFER_OUT",x);b->log("TRANSFER_IN",x);save();}}void list()const{for(auto&a:accounts)cout<<a->no()<<" | "<<a->type()<<" | "<<a->getBalance()<<'\n';}void run(){load();for(;;){cout<<"\nBanking System\n1 Open account 2 Transaction 3 Transfer 4 List 0 Exit\n";int c;if(!(cin>>c)||c==0){save();break;}if(c==1)open();else if(c==2)transact();else if(c==3)transfer();else if(c==4)list();}}};int main(){Bank{}.run();}
